    # one whose color occupies the fewest cells (the narrow separator).
    candidates = []
    for r in range(h):
        color = grid[r][0]
        if color != background and all(v == color for v in grid[r]):
            candidates.append((counts[color], "row", r, color))
    for c in range(w):
        color = grid[0][c]
        if color != background and all(grid[r][c] == color for r in range(h)):
            candidates.append((counts[color], "col", c, color))

    if not candidates:
        return [row[:] for row in grid]

    _, axis, index, marker_color = min(candidates)
