               for r in range(h) for c in range(w)
               if grid[r][c] != background and grid[r][c] != marker_color]
    if not objects:
        return [row[:] for row in grid]

    coords = [r if axis == "row" else c for r, c, _ in objects]
    lo, hi = min(coords), max(coords)

    if lo > index:
